const metrics = $input.all();
const dashboard = {};

for (const item of metrics) {
  const m = item.json;
  dashboard[m.metric] = {
    total: parseInt(m.total),
    qualified: parseInt(m.qualified),
    verified: parseInt(m.verified)
  };
}

// Calculer les KPIs
const kpis = {
  lead_to_qualified_rate: dashboard.leads?.total > 0 ? 
    Math.round((dashboard.leads.qualified / dashboard.leads.total) * 100) : 0,
  verification_rate: dashboard.leads?.total > 0 ? 
    Math.round((dashboard.leads.verified / dashboard.leads.total) * 100) : 0,
  prospect_quality_rate: dashboard.prospects?.total > 0 ? 
    Math.round((dashboard.prospects.qualified / dashboard.prospects.total) * 100) : 0
};

return [{json: {
  generated_at: new Date().toISOString(),
  metrics: dashboard,
  kpis,
  summary: {
    total_leads: dashboard.leads?.total || 0,
    qualified_leads: dashboard.leads?.qualified || 0,
    emails_sent_7d: dashboard.outreach?.qualified || 0,
    prospects_enriched: dashboard.prospects?.total || 0,
    posts_drafted: dashboard.linkedin_posts?.verified || 0,
    meetings_booked: dashboard.meetings?.qualified || 0
  }
}}];
